-- Base sintética produzida pelo commit 568bc75. Nenhum dado de produção.
BEGIN TRANSACTION;
CREATE TABLE approvals(month TEXT PRIMARY KEY,payload TEXT NOT NULL,created TEXT NOT NULL,evidence TEXT NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY,created TEXT NOT NULL,action TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE commercial(id INTEGER PRIMARY KEY,day TEXT,city TEXT NOT NULL,os TEXT NOT NULL,contract TEXT NOT NULL,tss TEXT NOT NULL,cause TEXT NOT NULL,form TEXT NOT NULL,family TEXT NOT NULL,closed INTEGER NOT NULL,inactive INTEGER NOT NULL,raw_hash TEXT NOT NULL);
CREATE TABLE geo(month TEXT PRIMARY KEY,mode TEXT NOT NULL,total INTEGER,cities TEXT NOT NULL,evidence TEXT NOT NULL);
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE prices(code TEXT NOT NULL,effective TEXT NOT NULL,cents INTEGER NOT NULL CHECK(cents>=0),active INTEGER NOT NULL,PRIMARY KEY(code,effective));
CREATE TABLE reviews(visit_id INTEGER NOT NULL,month TEXT NOT NULL,decision TEXT NOT NULL,code TEXT,evidence TEXT NOT NULL,PRIMARY KEY(visit_id,month));
CREATE TABLE revision(id INTEGER PRIMARY KEY CHECK(id=1),value INTEGER NOT NULL);
CREATE TABLE rules(id INTEGER PRIMARY KEY,tss TEXT NOT NULL,cause TEXT NOT NULL DEFAULT '',form TEXT NOT NULL DEFAULT '',effective TEXT NOT NULL,code TEXT,decision TEXT NOT NULL,evidence TEXT NOT NULL,UNIQUE(tss,cause,form,effective));
CREATE TABLE services(code TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE INDEX commercial_period ON commercial(day,closed,tss);
CREATE INDEX commercial_os ON commercial(contract,os);
COMMIT;
PRAGMA user_version=1;
